INSERT INTO `chattable` VALUES (1, '太湖', '太湖位于中国江苏省和浙江省之间，是中国最大的淡水湖之一，也是全国五大淡水湖之一。太湖面积约为2,400平方公里，蕴含着丰富的生态资源和文化遗产。太湖四周的山水、古迹、民俗艺术等各种风光和景观，吸引了众多游客前来观光旅游，太湖也成为中国著名的旅游胜地之一。', '1001', '王小明', '2024-02-13 07:59:01', '男', '2001-10-11');
INSERT INTO `chattable` VALUES (2, '千岛湖', '千岛湖是浙江省杭州市淳安县下辖的一个风景区。由于湖岸边上镶嵌着众多若干个大小不一的岛屿，因此得名千岛湖。千岛湖地处浙江西南山区，是一座以水、山、岛、林、泉、瀑为主要景观的自然风景区，素有“世界林水之都”、“中国最美的湖泊”等美誉。\n\n千岛湖水域面积广达千余平方公里，其中湖面面积三百多平方公里。湖水清澈透明，四季景色各异，景色秀丽诱人。湖中岛屿众多，由于形状、大小各异，而得名“千岛湖”。湖畔周围山峦起伏，密林深深，风景秀美。千岛湖区域内还有很多自然景点，如马岭河瀑布、樟林漂流、龙山峡谷、橄榄树园等等，也是众多景点中的精华。\n\n千岛湖的景观不仅吸引了众多游客，也成为了许多电影、电视剧的拍摄胜地。因此，千岛湖也成为了国内外游客和艺术家们向往的旅游胜地。', '1001', '王小明', '2024-02-13 08:00:07', '男', '2001-10-11');
INSERT INTO `chattable` VALUES (3, '苏州大学应用技术学院', '苏州大学应用技术学院创建于2002年，是苏州大学成立的第二所独立学院，也是苏州市唯一的以应用技术为主业的本科院校。学院位于苏州市苏州工业园区独墅湖高教区，校园环境优美，占地面积1600余亩。学院现有15个本科专业，分别涉及物联网工程、机械设计制造及其自动化、材料成型及控制工程、数字媒体技术、电子信息工程等多个学科领域。学院的师资力量雄厚，现有教职工近700人，其中教授、副教授占95%以上。\n\n学院一直致力于把握新时代人才培养的趋势，坚持以工业现场为教学点，引进企业工程师担任专业教师，并加强对学生的企业实践和职业素质培养。学院与多家知名企业合作开展产教融合教学，如中石化、日立等，学院还建立了完善的实习实训基地，为学生提供实践完备的机会，加速学生产业化流程。\n\n苏州大学应用技术学院秉承“务实创新，开明办学”的办学理念，始终坚持为学生提供优质的教育资源，培养学生的实践能力和创新意识，为国家和地方的工业发展与经济增长做出贡献。', '1001', '王小明', '2024-02-13 08:01:34', '男', '2001-10-11');
INSERT INTO `chattable` VALUES (4, 'chatGPT', 'Hello there! Is there anything I can help you with?', '1001', '王小明', '2024-02-13 08:06:05', '男', '2001-10-11');
INSERT INTO `chattable` VALUES (6, '西湖', '西湖位于中国浙江省杭州市西湖区，是中国最著名的湖泊之一。它被誉为中国十大名胜之一、世界自然遗产和世界文化遗产。西湖的湖水面积约为6.39平方公里，湖中有三座岛屿，分别是南屏山、北山和花港观鱼。西湖四周环绕着山丘，风景十分优美，是中国特色园林艺术的代表之一。西湖还有很多著名的景点，比如岳庙、雷峰塔、断桥残雪等等，每年吸引了大量的游客前来观赏。', '1001', '王小明', '2024-02-13 08:07:26', '男', '2001-10-11');
INSERT INTO `chattable` VALUES (7, '苏州2020年GDPGDP', '2020年苏州市GDP为1.95万亿元人民币。', '1001', '王小明', '2024-02-13 08:08:01', '男', '2001-10-11');
INSERT INTO `chattable` VALUES (8, '赛里木湖', '赛里木湖位于中国新疆维吾尔自治区伊犁哈萨克自治州克孜勒苏柯尔克孜自治州阿图什市和巴音郭楞蒙古自治州若羌县交界处，是中国第二大咸水湖，也是亚洲最大的内陆咸水湖之一。湖面面积约为5,580平方公里，湖水有丰富的盐和矿物质，常年湖面呈碧绿色。湖周围有著名的刀郎山、干柿子沟、铁克里克峡谷等自然景观。赛里木湖被誉为“光明的明珠，中国的马尔莎斯”，是中国重要的旅游胜地和畜牧业区域。', '1001', '王小明', '2024-02-13 08:08:49', '男', '2001-10-11');
