INSERT INTO `chattable` VALUES (59, '苏州大学应用技术学院在哪里', '苏州大学应用技术学院位于江苏省苏州市高新区狮山路999号。', '13811111111', '张三', '2024-04-06 07:37:13', '女', '2005-09-08');
INSERT INTO `chattable` VALUES (60, '苏州大学 应用技术学院', '苏州大学应用技术学院是苏州大学下属的一个学院，位于江苏省苏州市高新区仁爱路甲28号，是苏州市高新区高等教育园区中的重要高校之一，是省内唯一一所以“应用技术”命名的普通本科院校。\n\n学院成立于2001年，前身是苏州大学电子信息工程学院。经过多年的发展，学院现拥有7个本科专业以及2个专升本（继续教育）专业，分别为电子信息工程、通信工程、计算机科学与技术、软件工程、网络工程、自动化、物联网工程、高等教育自考本科（电子信息工程）、高等教育自考本科（计算机科学与技术）。\n\n学院注重实践教学，拥有完备的实验设备和实验室，与多家企业签订了产学研合作协议，开设了多门实训课程，使学生能够将理论知识与实践相结合。同时，学院还注重学生成才素质培养，积极开展智育、体育、美育、劳动教育等全方位的素质拓展活动。\n\n学院拥有一批高素质、高水平的师资队伍，其中教授、副教授占比56%，硕士以上学历占比90%左右。学院积极推动教师的教学成果转化，用自主创新推动学院的不断发展。', '13811111111', '张三', '2024-04-06 07:38:15', '女', '2005-09-08');
INSERT INTO `chattable` VALUES (61, '苏州最有名的景点', '1. 拙政园\n2. 虎丘\n3. 留园\n4. 老虎山公园\n5. 狮子林\n6. 吴文化博物馆\n7. 盘门景区\n8. 苏州博物馆\n9. 观前街\n10. 沧浪亭', '13811111111', '张三', '2024-04-06 07:38:47', '女', '2005-09-08');
INSERT INTO `chattable` VALUES (62, '苏州最有名的景点', '苏州最有名的景点包括： \n\n1. 拙政园 \n2. 留园 \n3. 虎丘山 \n4. 狮子林 \n5. 愚园 \n6. 盘门景区 \n7. 平江路 \n8. 金鸡湖 \n9. 沧浪亭 \n10. 周庄古镇。', '13811111111', '张三', '2024-04-06 07:41:45', '女', '2005-09-08');
INSERT INTO `chattable` VALUES (63, '苏州', '苏州是中国江苏省的一个历史名城，位于长江流域的东南部。苏州市总面积为8488平方公里，人口超过1000万。苏州是中国著名的旅游城市，有许多著名的园林、水乡、名胜古迹和美食，如拙政园、留园、狮子林、虎丘山、周庄、东山古镇、小吃等等。苏州是中国著名的文化名城，曾是吴文化的中心，拥有许多文化遗产和文化资源，如苏州博物馆、平江老街、苏州图书馆等等。苏州也是中国重要的经济核心城市，有许多著名的企业和科技园区，如苏州工业园区、华为苏州研究所、英特尔苏州工厂等等。', '13811111111', '张三', '2024-04-06 07:42:20', '女', '2005-09-08');
INSERT INTO `chattable` VALUES (64, '苏州最有名的景点', '调用openAI出错，不能为你提供chat服务！', '13811111111', '张三', '2024-04-06 07:43:11', '女', '2005-09-08');
INSERT INTO `chattable` VALUES (65, '大数据专业就业前景', '大数据专业的就业前景非常广阔，尤其是随着云计算、人工智能、物联网等新技术的发展，大数据分析和处理的需求也越来越大。以下是大数据专业的常见职业：\n\n1. 大数据工程师\n负责设计、架构和维护大数据处理平台与系统，拥有很高的技术要求。\n \n2. 大数据分析师\n运用数据挖掘、统计学、机器学习等分析方法，为企业提供数据驱动的决策支持。\n \n3. 大数据架构师\n负责指导和设计大数据架构，确保系统高效稳定，具有较强的管理和配置能力。\n\n4. 数据科学家\n深入挖掘数据背后的意义并对业务提出建议，需要具备数据分析能力和业务理解能力。\n\n5. 数据库管理员\n负责数据库的设计与管理，确保数据库的稳定性和安全性。\n \n6. 机器学习工程师\n利用机器学习和人工智能算法，处理海量数据并为业务提供解决方案。\n\n由此看来，大数据专业的就业前景非常乐观。', '13685153598', 'SM', '2024-04-06 13:48:57', '男', '1964-09-04');
INSERT INTO `chattable` VALUES (66, '俄乌战争何时能结束', '作为AI语言模型，我不能对未来做出预测或判断。当前，俄乌关系紧张，冲突不断，希望双方能够通过和平对话实现解决。', '13685153598', 'SM', '2024-04-06 13:50:49', '男', '1964-09-04');
INSERT INTO `chattable` VALUES (67, '新冠疫情何时能结束', '目前还无法确定新冠疫情何时能结束。虽然疫苗已经开始在全球范围内广泛使用，但仍面临许多挑战，如疫苗供应不足、病毒变异等。此外，全球各国疫情形势不同，一些国家已经开始逐渐放松封锁措施，而另一些国家仍在加强防控措施。因此，我们仍需保持警惕和耐心，积极配合各项防疫措施，做好自我防护，以期早日结束这场疫情。', '13685153598', 'SM', '2024-04-06 13:53:55', '男', '1964-09-04');
INSERT INTO `chattable` VALUES (68, '贵州', '贵州位于中国西南地区，是中国的一个省份。贵州地处喀斯特高原上，地形复杂，分布着许多山脉、丘陵和平原，拥有独特的自然风光和文化底蕴。贵州境内的旅游资源非常丰富，有众多世界闻名的景点，如黄果树瀑布、荔波小七孔、龙宫等。贵州还是中国少数民族聚居地之一，民族文化多元丰富，拥有独特的民族风情、手工艺品和美食文化等。', '15111111111', 'zjn', '2024-04-06 14:55:10', '女', '2002-09-08');
INSERT INTO `chattable` VALUES (69, '苏州在哪里？', '调用openAI出错，不能为你提供chat服务！', '15111111111', 'zjn', '2024-04-06 14:58:02', '女', '2002-09-08');
INSERT INTO `chattable` VALUES (70, '苏州十大景点', '1. 拙政园：中国传统园林艺术的典范，位于苏州市姑苏区东北部，占地面积5.2公顷。景点包括花园、园林、石刻、建筑等，是苏州园林中最有代表性的一座。\n\n2. 苏州博物馆：位于工业园区东方之门，是中国国家一级博物馆，展示了苏州地区的自然、历史和文化遗产。\n\n3. 留园：中国四大名园之一，坐落于苏州市姑苏区留园路。该园景点以精致的建筑、假山、水池、绿植等景观著称，是一座以水为主题的园林。\n\n4. 虎丘：又叫上方山，是苏州古城骨干景区之一，位于市区北面，是苏州“山水之间，极品”之一。景点包括“虎形岩”、“满园春色”、“小别墅”等。\n\n5. 拨浪鼓：是苏州最著名的古运河之一，也是一座传统园林，位于市区东北部的平江路。景点包括拨浪鼓桥、拨浪鼓亭、云香楼等，是苏州最受欢迎的集美食、文化、风景、购物为一体的商业街。\n\n6. 荷花池：位于苏州市相城区西南部，是苏州最大的坑塘扬水灌溉系统，也是一个集水产养殖、旅游观光、休闲娱乐为一体的景区。\n\n7. 金鸡湖：位于苏州工业园区中心，是中国最大的城市中心湖泊。景点包括周庄水乡、POP天文台、虹桥艺术中心等。\n\n8. 拈花湾：位于苏州市虎丘区虎丘西山，是苏州市的一处自然风景区。景点包括瀑布、松林、亭台、桥梁等，是一个可以欣赏自然风光和健身休闲的好去处。\n\n9. 瑞光塔：是苏州市南部的一座塔式建筑，位于高新区瑞光路。景点是长江三角洲地区文化和艺术交流中心，拥有音乐会、展览、会议等多种文化活动。\n\n10. 盘门景区：位于苏州市吴江区，是一个集旅游休闲、文化艺术、生态保护为一体的大型综合性景区。景点包括盘门景区大门、颜家园、释迦塔等。盘门景区是一个集游览、休闲、购物、娱乐为一体的地方，吸引了国内外众多游客。', '15111111111', 'zjn', '2024-04-12 08:10:53', '女', '2002-09-08');
INSERT INTO `chattable` VALUES (71, '苏州十大景点名称是什么？', '1. 虎丘\n2. 拙政园\n3. 留园\n4. 瑞光塔\n5. 北寺塔\n6. 金鸡湖\n7. 苏州博物馆\n8. 盘门景区\n9. 睡足街\n10. 周庄', '15111111111', '钟佳妮', '2024-04-12 08:14:15', '女', '2002-09-08');
