INSERT INTO `chattable` VALUES (83, '浙江南浔怎么样？', '浙江南浔是一个历史悠久、文化底蕴深厚的小镇，位于杭州市西湖区南部。这里的风景秀美，历史建筑保存完好，是一个适合游览和度假的地方。\n\n南浔镇是中国历史文化名镇，拥有众多的历史古迹和文化遗产，如古运河、慈恩寺、西店茶楼、凤凰楼等，体现了南浔的鲜明文化特色。此外，南浔还是一个自然资源十分丰富的地方，有南浔湖、潘家塘和西湖之间的湿地，是一个适合观赏、体验和探索的地方。\n\n总的来说，南浔镇是一个适合游览和度假的地方，既有历史文化古迹，又有自然风光，很值得一去。', '1001', '王小明', '2024-05-14 14:27:07', '男', '2001-10-11');
INSERT INTO `chattable` VALUES (84, '周庄在哪里？', '周庄位于中国江苏省苏州市昆山市境内。', '13685153598', 'SM', '2024-05-14 14:28:10', '男', '1964-09-04');
