INSERT INTO `chattable` VALUES (94, '泸沽湖', '泸沽湖是中国云南省和四川省交界的一座淡水湖，被称为“高原明珠”，位于鲁能山脉中段，东起丽江、西至盐源，面积为52.9平方公里，平均海拔2690米。泸沽湖以其奇特的地理环境、独特的摩梭民俗文化和清澈碧蓝的湖水而闻名于世。湖边居住着以摩梭族为主的多个少数民族，这里的人们有着独特的生活方式和风俗习惯，形成了一种特殊的母系社会文化。泸沽湖也是许多旅游者前往云南旅游的必去之地，游客可以在湖畔骑行、划船、徒步、跳踩踏舞、走访摩梭古寨等，欣赏湖光山色，感受民俗文化的独特魅力。', '13685153598', 'SM', '2024-09-19 12:53:00', '男', '1964-09-04');
INSERT INTO `chattable` VALUES (95, '苏州在哪里', '苏州位于中国江苏省中部，东南沿海地带。', '13685153598', 'SM', '2024-09-19 19:32:27', '男', '1964-09-04');
INSERT INTO `chattable` VALUES (96, '泸沽湖', '泸沽湖位于云南省和四川省交界处，是中国最大的高海拔淡水湖。湖水碧绿清澈，被誉为“世界上最美丽的湖泊之一”。周围群山环绕，风景秀美，尤其是湖畔村寨和摩梭人的风俗文化更是吸引着众多游客前来观赏和探访。泸沽湖是一个独特的旅游胜地，被评为国家AAAA级旅游景区。', '13685153598', 'SM', '2024-09-19 19:32:29', '男', '1964-09-04');
INSERT INTO `chattable` VALUES (97, '苏州', '苏州是江苏省下辖的地级市，位于长江三角洲东南部，地处长江和太湖之间，东临上海市，南接浙江省，西北毗邻无锡市，北与常州市相邻。是中国历史文化名城、园林之城、水乡之城和旅游胜地，有“东方威尼斯”之称。苏州市境内的古典园林，如拙政园、留园、熙园、网师园、环秀山庄等被列入了世界文化遗产。苏州的发展主要依靠创新，成为中国重要的高新技术产业基地之一。苏州还有许多特色美食，如苏州月饼、阳澄湖大闸蟹、灌汤包、松鼠桂鱼等都备受游客喜爱。', '18888888888', '188', '2024-09-19 19:46:01', '男', '2000-10-10');
INSERT INTO `chattable` VALUES (98, '泸沽湖', '泸沽湖是位于中国云南省和四川省之间、海拔2690米的高原湖泊，也是中国最大的高山湖泊之一。泸沽湖水深在40~93米之间，湖面面积为52.8平方公里，储水量为9.35亿立方米。泸沽湖四周的山峦、森林和草甸环绕，是一个著名的旅游胜地，也是摩梭族等少数民族的居住地之一。泸沽湖有丰富的动植物资源，其中包括四川金丝猴、红麂、蓝羚羊等野生动物，以及杜鹃花、柳杉等植物。泸沽湖的美景和独特的文化成为了吸引游客的主要原因之一。', '18888888888', '188', '2024-09-19 19:47:15', '男', '2000-10-10');
