INSERT INTO `chattable` VALUES (112, '泸沽湖', '泸沽湖位于中国四川省和云南省交界处，是一个高原湖泊，被誉为“世界上最后一个女儿国”，因为当地摩梭族民族社会结构特殊，以母系家庭为主。泸沽湖水域广阔，湖水清澈碧蓝，四周被雪峰环绕，景色壮丽。游客可以乘船游览湖景，欣赏自然美景，感受当地独特的摩梭族文化。泸沽湖也是许多摄影爱好者和文艺青年喜爱的拍摄和创作地点。', '13685153598', 'SM', '2024-09-22 08:10:48', '男', '1964-09-04');
INSERT INTO `chattable` VALUES (113, '泸沽湖', '泸沽湖是中国云南省和四川省交界处的一个高原湖泊，位于横断山脉的南部。泸沽湖被誉为“世界上最后一个女儿国”，因为当地摩梭族保留了独特的母系社会风俗和家庭结构。\n\n泸沽湖是一个美丽的山水风光之地，湖水清澈见底，四周被连绵的山峦环绕。游客们可以在湖边散步、骑行或乘船游览湖景，感受到大自然的宁静与神奇。\n\n除了风景秀丽，泸沽湖还因其独特的摩梭族文化而吸引着大量游客。游客们可以参观摩梭族的传统村落，了解他们的生活习俗和文化传统。\n\n总的来说，泸沽湖是一个充满神秘和魅力的地方，是游客们探索自然与文化的绝佳去处。', '13685153598', 'SM', '2024-09-23 19:40:06', '男', '1964-09-04');
INSERT INTO `chattable` VALUES (114, '苏州', '苏州是中国江苏省的一个城市，也被称为“江南小城”。苏州是一个历史悠久的城市，拥有许多古老的园林、古建筑和文化遗产。苏州园林被联合国教科文组织列为世界文化遗产，是中国最具代表性的园林之一。\n\n除了园林，苏州还以丰富的文化和历史遗产闻名，如苏州博物馆、秦淮河、七里山塘等。苏州也是中国著名的旅游胜地之一，每年吸引着大量国内外游客前来参观游览。\n\n苏州也是一个经济发达的城市，拥有发达的制造业、服务业和旅游业。苏州工业园区是中国最具知名度的高新技术园区之一，吸引了大量国内外企业前来投资兴业。\n\n总的来说，苏州是一个兼具古风和现代气息的城市，是中国的历史文化名城，也是一个蓬勃发展的现代化城市。', '13685153598', 'SM', '2024-10-07 20:13:49', '男', '1964-09-04');
INSERT INTO `chattable` VALUES (115, '徐州在哪里', '徐州是中国江苏省下辖的地级市，位于中国东部。其地理位置大致位于江苏省北部，毗邻山东省和安徽省。', '13685153598', 'SM', '2024-10-08 19:40:29', '男', '1964-09-04');
